def _blocked_cholesky(data: torch.Tensor, output: torch.Tensor) -> torch.Tensor:
    if output.shape[0] == 1:
        _ext.lower_copy_(data, output)
    else:
        output.copy_(data)
    n = output.shape[-1]
    if output.shape[0] == 1:
        block = 4096
    elif n == 1024:
        block = 256
    else:
        block = 128

    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        torch.backends.cuda.matmul.allow_tf32 = True
        for k in range(0, n, block):
            stop = min(k + block, n)
            diagonal = output[:, k:stop, k:stop]
            if output.shape[0] == 1:
                factor = torch.linalg.cholesky_ex(
                    diagonal,
                    check_errors=False,
                    out=(_factor_workspace, _factor_info),
                ).L
            else:
                factor = torch.linalg.cholesky_ex(
                    diagonal, check_errors=False
                ).L
            if output.shape[0] == 1:
                _ext.copy_factor_lower_(factor, diagonal)
            else:
                diagonal.copy_(factor)
            if stop == n:
                continue

            panel = output[:, stop:, k:stop]
            if output.shape[0] == 1:
                _ext.trsm_(factor, panel)
                half_panel = _half_workspace[: panel.shape[1]]
                _ext.convert_panel_(panel[0], half_panel)
                _triangular_rankk_(
                    output[0, stop:, stop:], half_panel
                )
            else:
                solved = torch.linalg.solve_triangular(
                    factor,
                    panel.transpose(-2, -1),
                    upper=False,
                ).transpose(-2, -1)
                panel.copy_(solved)
                _ext.fp16_update_(
                    output[:, stop:, stop:], solved.to(torch.float16)
                )
    finally:
        torch.backends.cuda.matmul.allow_tf32 = old_tf32

    if output.shape[0] == 1:
        return output
    return output.tril_()


def _high_batch_1024_cholesky(
    data: torch.Tensor,
    output: torch.Tensor,
    stages,
) -> torch.Tensor:
    global _batch_trsm_pointers
    global _batch_factor_workspace, _batch_factor_info
    _ext.batch_lower_copy_cuda(data, output)

    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        torch.backends.cuda.matmul.allow_tf32 = True
        for diagonal, panel, rankk_stage in stages:
            factor = torch.linalg.cholesky_ex(
                diagonal,
                check_errors=False,
                out=(_batch_factor_workspace, _batch_factor_info),
            ).L
            if rankk_stage is None:
                _ext.prepare_batch_factor_and_pointers_cuda(
                    factor, diagonal, panel, _batch_trsm_pointers
                )
                continue
            _ext.prepare_batch_factor_and_pointers_cuda(
                factor, diagonal, panel, _batch_trsm_pointers
            )
            _ext.batch_panel_solve_(
                factor, panel, _batch_trsm_pointers
            )
            _batched_triangular_rankk_(
                rankk_stage[2],
                rankk_stage[3],
                rankk_stage[4],
            )
    finally:
        torch.backends.cuda.matmul.allow_tf32 = old_tf32
    _ext.batch_zero_upper_cuda(output)
    return output


